  qty DECIMAL(12, 3) NOT NULL DEFAULT 1,
  unit_price DECIMAL(12, 3) NOT NULL DEFAULT 0,
  line_total DECIMAL(12, 3) NOT NULL DEFAULT 0,
  sort_order INT NOT NULL DEFAULT 0,
  discount_pct DECIMAL(5, 2) NOT NULL DEFAULT 0
);

