  status VARCHAR(20) NOT NULL DEFAULT 'draft'::character varying,
  notes TEXT,
  subtotal DECIMAL(12, 3) NOT NULL DEFAULT 0,
  total DECIMAL(12, 3) NOT NULL DEFAULT 0,
  amount_paid DECIMAL(12, 3) NOT NULL DEFAULT 0,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMP DEFAULT now(),
  updated_at TIMESTAMP DEFAULT now(),
  type VARCHAR(10) NOT NULL DEFAULT 'invoice'::character varying
);

