  location_id UUID NOT NULL REFERENCES locations(id),
  qty_delta DECIMAL(10, 3) NOT NULL,
  reason VARCHAR(255) NOT NULL,
  new_batch_id UUID REFERENCES raw_material_batches(id),
  created_by UUID REFERENCES users(id),
  created_at TIMESTAMP DEFAULT now()
);

CREATE TABLE stock_transfers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  raw_material_id UUID NOT NULL REFERENCES raw_materials(id),
  from_location_id UUID NOT NULL REFERENCES locations(id),
  to_location_id UUID NOT NULL REFERENCES locations(id),
  qty DECIMAL(10, 3) NOT NULL,
  new_batch_id UUID REFERENCES raw_material_batches(id),
  transferred_by UUID REFERENCES users(id),
  created_at TIMESTAMP DEFAULT now()
);

CREATE TABLE subscription_purchases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,
  subscription_id UUID NOT NULL UNIQUE,
  invoice_id UUID NOT NULL UNIQUE,
  status VARCHAR(20) NOT NULL DEFAULT 'open'::character varying,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  completed_at TIMESTAMPTZ,
  voided_at TIMESTAMPTZ,
  replaces_subscription_id UUID,
  CONSTRAINT subscription_purchases_invoice_fk FOREIGN KEY (invoice_id, company_id, subscription_id) REFERENCES invoices(id, company_id, subscription_id) ON DELETE RESTRICT,
  CONSTRAINT subscription_purchases_replaces_fk FOREIGN KEY (replaces_subscription_id, company_id) REFERENCES subscriptions(id, company_id) ON DELETE RESTRICT,
  CONSTRAINT subscription_purchases_subscription_fk FOREIGN KEY (subscription_id, company_id) REFERENCES subscriptions(id, company_id) ON DELETE RESTRICT
);

CREATE TABLE subscriptions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  plan VARCHAR(20) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'active'::character varying,
  monthly_price DECIMAL(10, 3),
  auto_renew BOOLEAN DEFAULT true,
  next_billing_date TIMESTAMP,
  created_at TIMESTAMP DEFAULT now(),
  updated_at TIMESTAMP DEFAULT now(),
  currency VARCHAR(3) NOT NULL,
  billing_interval VARCHAR(10) NOT NULL,
  current_period_start TIMESTAMPTZ NOT NULL,
  current_period_end TIMESTAMPTZ NOT NULL,
  period_amount DECIMAL(10, 3) NOT NULL,
  UNIQUE (id, company_id)
);

CREATE TABLE suppliers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  name VARCHAR(255) NOT NULL,
  contact_name VARCHAR(255),
  phone VARCHAR(20),
  email VARCHAR(255),
  notes TEXT,
  created_at TIMESTAMP DEFAULT now(),
  updated_at TIMESTAMP DEFAULT now()
);

CREATE TABLE support_tickets (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  created_by UUID NOT NULL REFERENCES users(id),
  subject VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  status VARCHAR(20) DEFAULT 'open'::character varying,
  priority VARCHAR(20) DEFAULT 'medium'::character varying,
  created_at TIMESTAMP DEFAULT now(),
  updated_at TIMESTAMP DEFAULT now(),
  category VARCHAR(30) NOT NULL DEFAULT 'general'::character varying,
  assigned_to UUID REFERENCES users(id),
  first_response_at TIMESTAMP,
  resolved_at TIMESTAMP,
  sla_response_due_at TIMESTAMPTZ,
  sla_resolution_due_at TIMESTAMPTZ,
  sla_response_breached BOOLEAN DEFAULT false,
  sla_resolution_breached BOOLEAN DEFAULT false,
  escalation_level INT DEFAULT 0,
  escalated_to UUID REFERENCES users(id),
  escalated_at TIMESTAMP,
  category_id UUID REFERENCES ticket_categories(id) ON DELETE SET NULL,
  request_type_id UUID REFERENCES service_request_types(id) ON DELETE SET NULL,
  dynamic_data JSONB DEFAULT '{}'::jsonb,
  ticket_number VARCHAR(50),
  attachments JSONB NOT NULL DEFAULT '[]'::jsonb,
  sla_response_escalated_at TIMESTAMPTZ,
  sla_resolution_escalated_at TIMESTAMPTZ,
  sla_last_swept_at TIMESTAMPTZ
);

CREATE TABLE sync_tokens (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id),
  device_id VARCHAR(255),
  last_sync_timestamp TIMESTAMP,
